sys_script_client.script:
function onSubmit() {
    var empName = g_form.getValue('employee');
    if (empName == '') {
        g_form.addErrorMessage('Enter employee name');
        return false;
    }

    var eqpType = g_form.getValue('equipment_type');
    if (eqpType == '') {
        g_form.addErrorMessage('Select equipment type');
        return false;
    }

    var reqReason = g_form.getValue('request_reason');
    if (reqReason == '') {
        g_form.addErrorMessage('Enter request reason');
        return false;
    }

    var retDate = g_form.getValue('expected_return_date');
    var reqDate = g_form.getValue('required_date');

    if (retDate && reqDate && retDate <= reqDate) {
        g_form.addErrorMessage('Select return date after request date');
        return false;
    }

    return true;
}
